import React from 'react';

export default function Careers() {
    return (
        <section
            id="careers"
            className="min-h-screen py-12 px-4 flex flex-col justify-center items-center bg-gradient-to-br from-white/80 via-blue-50 to-pink-50 dark:from-gray-900 dark:via-blue-950 dark:to-purple-950 transition-colors duration-500"
        >
            <div className="container mx-auto max-w-5xl px-4">
                <h2 className="text-3xl sm:text-4xl font-extrabold mb-6 gradient-text drop-shadow-lg text-center">
                    Careers at AB Recruiters
                </h2>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                    {/* Join Our Team */}
                    <div className="bg-white/90 dark:bg-gray-800/80 rounded-xl p-6 shadow-md border border-blue-200/50 transition-all duration-200 hover:shadow-lg hover:border-blue-400/70">
                        <h3 className="text-2xl font-bold mb-4 text-blue-600">Join Our Team</h3>
                        <p className="text-gray-600 dark:text-gray-300 text-sm sm:text-base">
                            Become a part of a growing organization that values excellence, innovation, and teamwork. We offer a professional environment that encourages learning and growth while recognizing individual contributions.
                        </p>
                    </div>

                    {/* Current Openings */}
                    <div className="bg-white/90 dark:bg-gray-800/80 rounded-xl p-6 shadow-md border border-green-200/50 transition-all duration-200 hover:shadow-lg hover:border-green-400/70">
                        <h3 className="text-2xl font-bold mb-4 text-green-600">Current Openings</h3>
                        <p className="text-gray-600 dark:text-gray-300 text-sm sm:text-base">
                            We also have multiple openings across various roles within AB Recruiters. If you are looking to explore new opportunities, we welcome your application.
                        </p>
                    </div>
                </div>

                <div className="mt-8 bg-white/90 dark:bg-gray-800/80 rounded-xl p-6 shadow-md border border-pink-200/50 transition-all duration-200 hover:shadow-lg hover:border-pink-400/70">
                    <h3 className="text-2xl font-bold mb-4 text-pink-600">How to Apply</h3>
                    <p className="text-gray-600 dark:text-gray-300 text-sm sm:text-base">
                        To apply for open positions or to express your interest in joining our team, please email your updated resume to <a href="mailto:hr@abrecruiters.com" className="text-blue-600 hover:text-pink-500 font-bold transition-colors duration-200">hr@abrecruiters.com</a> mentioning the position or career area you wish to apply for.
                    </p>
                </div>

                <p className="text-center text-gray-600 dark:text-gray-300 text-sm sm:text-base mt-8">
                    Together, let’s shape the future of talent acquisition.
                </p>
            </div>
        </section>
    );
}